<div class="card"><div class="row" style="justify-content:space-between"><span class="lbl">Open interest · 30 days</span><span style="font-size:13px;font-weight:500">${arw(T.oi[0])}</span></div><div style="font-size:13px;line-height:1.4;margin:4px 0 6px">${T.oi[1]}.</div>${line(dv.OI,'var(--bl)')}</div>
