s+=`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${r.toFixed(1)}" fill="${c}" fill-opacity="${p[4]?.3:.16}" stroke="${c}" stroke-width="${p[4]?1.5:.75}" stroke-opacity="${p[4]?1:.5}"><title>${p[0]} · attention ${p[1].toFixed(1)}× its weekly norm (${f0(p[8])} mentions) · open interest ${sg(p[2])} in 24h, ${sg(p[6])} in 4h, ${sg(p[5])} in 1h · price ${sg(p[7])}</title></circle>`;
