function tapeRow(t){const C={L:'var(--up)',C:'var(--ups)',S:'var(--dn)',X:'var(--dns)',N:'var(--surface-0)'},T={L:'price up, OI up — longs opening',C:'price up, OI down — shorts covering',S:'price down, OI up — shorts opening',X:'price down, OI down — longs closing',N:'quiet hour'};
return `<div style="display:flex;gap:2px" role="img" aria-label="Hour-by-hour positioning, last 24 hours">${t.split('').map((k,i)=>`<span title="${t.length-i}h ago · ${T[k]}" style="flex:1;height:12px;border-radius:2px;background:${C[k]};${k=='C'?'box-shadow:inset 0 0 0 1px var(--up)':k=='X'?'box-shadow:inset 0 0 0 1px var(--dn)':''}"></span>`).join('')}</div>`}
function tfGrid(tf){const bg=(v,vol)=>{const a=vol?Math.min(1,Math.max(0,(v-1)/3)):Math.min(1,Math.abs(v)/12);return vol?`rgba(42,120,214,${(.06+a*.3).toFixed(2)})`:v>=0?`rgba(15,157,106,${(.06+a*.34).toFixed(2)})`:`rgba(224,51,76,${(.06+a*.34).toFixed(2)})`};
return `<table style="width:100%;border-collapse:separate;border-spacing:3px;font-size:12px"><tr><th style="border:0;padding:0"></th>${['1h','4h','24h'].map(h=>`<th style="border:0;padding:0 0 1px;text-align:center;font-size:11px">${h}</th>`).join('')}</tr>${tf.map((r,i)=>`<tr><td style="border:0;padding:0 4px 0 0;color:var(--text-muted);font-size:11px;white-space:nowrap">${r[0]}</td>${r.slice(1).map(v=>`<td class="n" style="border:0;text-align:center;border-radius:5px;padding:5px 2px;font-weight:500;background:${bg(v,i==2)}">${i==2?v.toFixed(1)+'×':sg(v)}</td>`).join('')}</tr>`).join('')}</table>`}
function meter(m){const c=m[2]=='r'?'var(--dn)':m[2]=='a'?'var(--am)':m[2]=='g'?'var(--up)':'var(--nt)';
return `<div><div class="row" style="justify-content:space-between;gap:4px;flex-wrap:nowrap"><span class="lbl" style="font-size:11px;white-space:nowrap">${m[0]}</span><span class="n" style="font-size:12px;font-weight:500;color:${m[2]=='r'?'var(--dn)':'var(--text-primary)'};white-space:nowrap">${m[1]}</span></div><div style="position:relative;height:4px;border-radius:2px;background:var(--surface-0);margin-top:4px">${m[3]==null?'':`<span style="position:absolute;left:calc(${(m[3]*100).toFixed(0)}% - 4px);top:-3px;width:8px;height:10px;border-radius:3px;background:${c}"></span>`}</div></div>`}
function duoLv(a,b,lv){const W=300,H=112,X0=40,X1=258,T=20,B=108,lo=Math.min(...a,lv.go,lv.stop),hi=Math.max(...a,lv.go,lv.stop),rg=hi-lo||1,Y=v=>T+(hi-v)/rg*(B-T),ol=Math.min(...b),oh=Math.max(...b),og=(oh-ol)||1,YO=v=>B-(v-ol)/og*(B-T)*.85,X=i=>X0+i/(a.length-1)*(X1-X0),gc=lv.side=='short'?'var(--dn)':lv.side=='long'?'var(--up)':'var(--text-muted)';
const fmt=v=>v>=1000?Math.round(v).toLocaleString('en-US'):v>=10?v.toFixed(2):v>=.01?v.toFixed(4):v.toPrecision(3),fo=v=>v>=1000?'$'+(v/1000).toFixed(2)+'B':'$'+Math.round(v)+'M';
let s=`<text x="${X0}" y="11" font-size="10.5" fill="var(--text-secondary)"><tspan fill="var(--bl)" font-weight="500">▮</tspan> OI (left)   <tspan fill="var(--am)" font-weight="500">━</tspan> Price (right) · 3 days</text>`;
[0,.5,1].forEach(t=>{const v=ol+og*t,y=YO(v);s+=`<line x1="${X0}" y1="${y.toFixed(1)}" x2="${X1}" y2="${y.toFixed(1)}" stroke="var(--border)"/><text x="${X0-3}" y="${(y+3).toFixed(1)}" font-size="9.5" text-anchor="end" fill="var(--bl)">${fo(v)}</text>`});
[0,.5,1].forEach(t=>{const v=lo+rg*t;s+=`<text x="${X1+3}" y="${(Y(v)+3).toFixed(1)}" font-size="9.5" fill="var(--am)">${fmt(v)}</text>`});
const bp=b.map((v,i)=>X(i*(a.length-1)/(b.length-1)).toFixed(1)+','+YO(v).toFixed(1)).join(' ');
s+=`<polygon fill="var(--bl)" opacity=".14" points="${X0},${B} ${bp} ${X1},${B}"/><polyline fill="none" stroke="var(--bl)" stroke-width="1.5" stroke-linejoin="round" points="${bp}"/>`;
s+=`<line x1="${X0}" y1="${Y(lv.go).toFixed(1)}" x2="${X1}" y2="${Y(lv.go).toFixed(1)}" stroke="${gc}" stroke-width="1.3" stroke-dasharray="5 3"/><line x1="${X0}" y1="${Y(lv.stop).toFixed(1)}" x2="${X1}" y2="${Y(lv.stop).toFixed(1)}" stroke="var(--text-muted)" stroke-width="1" stroke-dasharray="2 3"/>`;
s+=`<polyline fill="none" stroke="var(--am)" stroke-width="1.8" stroke-linejoin="round" points="${a.map((v,i)=>X(i).toFixed(1)+','+Y(v).toFixed(1)).join(' ')}"/>`;
return `<svg width="100%" viewBox="0 0 ${W} ${H}" role="img" aria-label="Open interest (left axis) and price (right axis) over the last three days, with the entry-trigger and setup-fails levels" style="display:block">${s}</svg>`}
function radar(el,d){rcss();el.classList.add('atk');
const SP={1:['vw','Long setup'],2:['vr','Short setup'],3:['vn','No trade']},ar=s=>s>0?'<span class="up">▲</span>':s<0?'<span class="dn">▼</span>':'<span class="mu">·</span>';
const smBar=m=>{if(!m)return `<div class="row" style="justify-content:space-between"><span class="lbl" style="font-size:11px">Smart money</span><span class="sub">no position among the top 100</span></div>`;const t=m.l+m.s||1;
return `<div><div class="row" style="justify-content:space-between;flex-wrap:nowrap"><span class="lbl" style="font-size:11px">Smart money</span><span class="n" style="font-size:13px;font-weight:500">${m.net}</span></div><div style="display:flex;height:16px;border-radius:4px;overflow:hidden;gap:2px;margin:4px 0 3px"><span class="n" style="width:${(m.l/t*100).toFixed(0)}%;min-width:44px;background:var(--ups);color:var(--up);font-size:11px;line-height:16px;padding:0 5px;white-space:nowrap">${m.lS} long</span><span class="n" style="flex:1;min-width:48px;background:var(--dns);color:var(--dn);font-size:11px;line-height:16px;padding:0 5px;text-align:right;white-space:nowrap">${m.sS} short</span></div><div class="sub" style="font-size:11px">${m.sub}</div></div>`};
const card=c=>`<div class="card rc" style="gap:10px;${c.k==1?'border:1.5px solid var(--up)':c.k==2?'border:1.5px solid var(--dn)':''}"><div class="row" style="justify-content:space-between;flex-wrap:nowrap"><span class="row" style="gap:6px"><span style="font-size:20px;font-weight:500">${c.ccy}</span><span class="chip">${c.theme}</span></span><span class="vd ${SP[c.k][0]}">${SP[c.k][1]}${c.k<3?' · '+c.conv:''}</span></div>
<div class="row" style="justify-content:space-between;align-items:baseline"><span class="row" style="align-items:baseline;gap:8px"><span class="v n">${c.lastS}</span><span class="n ${cl(c.chg24)}" style="font-size:14px;font-weight:500">${sg(c.chg24)}</span></span><span class="p">${c.stage}</span></div>
<div style="font-size:13.5px;line-height:1.35;font-weight:500">${c.tag}</div>
<div class="g" style="grid-template-columns:repeat(3,minmax(0,1fr));gap:6px">${c.abs.map(a=>`<div style="background:var(--surface-0);border-radius:8px;padding:6px 8px;min-width:0"><div class="lbl" style="font-size:11px;white-space:nowrap">${a[0]}</div><div class="n" style="font-size:15px;font-weight:500;white-space:nowrap">${a[1]}</div><div class="sub n" style="font-size:11px;white-space:nowrap">${a[2]}</div>${a[3]&&a[3].length>1?`<div title="Mentions per 4 hours, last 48 hours" style="display:flex;align-items:flex-end;gap:1.5px;height:16px;margin-top:4px">${a[3].map((v,i,A)=>`<span style="flex:1;border-radius:1px;background:var(--bl);opacity:${i>=A.length-2?1:.45};height:${Math.max(8,v/Math.max(...A,1)*100).toFixed(0)}%"></span>`).join('')}</div>`:''}</div>`).join('')}</div>
<div>${duoLv(c.px,c.oi,c.lv)}<div class="row n" style="justify-content:space-between;font-size:12px;margin-top:5px">${c.lv.side=='long'?`<span><span class="up" style="font-weight:500">Enter long above ${c.lv.goS}</span></span><span class="mu">setup fails below ${c.lv.stopS}</span>`:c.lv.side=='short'?`<span><span class="dn" style="font-weight:500">Enter short below ${c.lv.goS}</span></span><span class="mu">setup fails above ${c.lv.stopS}</span>`:`<span class="mu">12h range ${c.lv.stopS} – ${c.lv.goS}</span>`}</div></div>
${tfGrid(c.tf)}
${c.pos?`<div><div class="lbl" style="font-size:11px;margin-bottom:4px">Who is long · who is short</div>${c.pos.map(r=>`<div style="margin-bottom:6px"><div class="row" style="justify-content:space-between;flex-wrap:nowrap;gap:6px;font-size:11.5px"><span style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${r[0]}</span><span class="n mu" style="white-space:nowrap">${r[2]}</span></div>${r[1]==null?'':`<div style="display:flex;height:14px;border-radius:4px;overflow:hidden;gap:2px;margin-top:3px"><span class="n" style="width:${r[1]}%;min-width:30px;background:var(--ups);color:var(--up);font-size:11px;line-height:14px;padding:0 5px">${r[1]}%</span><span class="n" style="flex:1;min-width:30px;background:var(--dns);color:var(--dn);font-size:11px;line-height:14px;padding:0 5px;text-align:right">${100-r[1]}%</span></div>`}</div>`).join('')}</div>`:smBar(c.sm)}
${d.evidence?`<div><div class="lbl" style="font-size:11px;margin-bottom:2px">Evidence · ▲ votes long · ▼ votes short</div><div class="g" style="grid-template-columns:minmax(0,1fr);gap:0">${c.ev.map(e=>`<div class="row" style="justify-content:space-between;flex-wrap:nowrap;gap:6px;font-size:12px;padding:2px 0"><span style="white-space:nowrap">${ar(e[2])} ${e[0]}</span><span class="n mu" style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${e[1]}</span></div>`).join('')}</div></div>`:''}
${c.driver?`<div style="font-size:12.5px;line-height:1.4;color:var(--text-secondary)">${c.driver}</div>`:''}${c.note?`<div class="row" style="gap:6px;font-size:12px;padding:5px 8px;border-radius:6px;background:rgba(237,161,0,.14)"><span class="dot" style="background:var(--am)"></span><span>${c.note}</span></div>`:''}${d.plan?`<button data-ccy="${c.ccy}" style="margin-top:auto">Design a position for ${c.ccy} ↗</button>`:''}</div>`;
const lg=(c,t,b)=>`<span class="row" style="gap:4px"><i style="width:12px;height:10px;border-radius:2px;background:${c};${b?'box-shadow:inset 0 0 0 1px '+b:''}"></i>${t}</span>`,dt=(c,t)=>`<span class="row" style="gap:4px"><span class="dot" style="background:${c}"></span>${t}</span>`;
el.innerHTML=`<h2 style="position:absolute;left:-9999px">${esc(d.head)}</h2>
<div class="card" style="margin-bottom:10px"><div class="row" style="justify-content:space-between;align-items:baseline;margin-bottom:8px"><span class="big" style="margin:0">${d.head}</span><span class="lbl">${d.scanned} alt perpetuals scanned on OKX · as of ${d.asof}</span></div>
<div class="row sub" style="margin-bottom:2px">${dt('var(--up)','long setup')}${dt('var(--dn)','short setup')}${dt('var(--am)','no trade')}${dt('var(--nt)','rest of the market')}<span>bubble = 24h volume</span></div>${radarMap(d.pts,d.thrX,d.thrY)}</div>
<div class="row sub" style="margin:0 2px 8px;gap:10px"><span style="color:var(--text-primary);font-weight:500">Candidates</span><span class="row" style="gap:4px"><i style="width:12px;height:0;border-top:1.5px dashed var(--text-secondary)"></i>entry trigger</span><span class="row" style="gap:4px"><i style="width:12px;height:0;border-top:1px dotted var(--text-muted)"></i>setup fails</span></div>
<div class="g" style="grid-template-columns:repeat(auto-fit,minmax(290px,1fr));margin-bottom:10px">${d.cards.map(card).join('')}</div>${d.passed&&d.passed.length?`<div class="card" style="margin-bottom:10px;padding:10px 16px"><div class="row" style="gap:6px 14px"><span class="lbl">Checked and passed over</span>${d.passed.map(x=>`<span style="font-size:12.5px"><span class="dot" style="background:var(--am);margin-right:5px"></span><b style="font-weight:500">${x[0]}</b> <span class="mu">${x[1]}</span></span>`).join('')}</div></div>`:''}<div class="sub">${d.foot}</div>`;
el.querySelectorAll('button[data-ccy]').forEach(b=>b.onclick=()=>window.sendPrompt&&sendPrompt(`Design a position for ${b.dataset.ccy}.`))}
function positionCard(el,d){rcss();el.classList.add('atk');const L=d.side=='long',c=L?'var(--up)':'var(--dn)',
row=(k,v,sub,cls)=>`<div style="display:flex;justify-content:space-between;align-items:baseline;gap:12px;padding:9px 0;border-top:0.5px solid var(--border)"><span style="font-size:13px;color:var(--text-secondary);white-space:nowrap">${k}</span><span style="text-align:right"><span class="n ${cls||''}" style="font-size:17px;font-weight:500">${v}</span>${sub?` <span class="n mu" style="font-size:12px;white-space:nowrap">${sub}</span>`:''}</span></div>`;
el.innerHTML=`<h2 style="position:absolute;left:-9999px">Recommended ${d.ccy} ${d.side} position: entry ${d.entry}, stop ${d.stop}, targets ${d.tp1} and ${d.tp2}, ${d.contracts} contracts at ${d.lever}x</h2>
<div class="card" style="max-width:460px;margin:0 auto;border:1.5px solid ${c};padding:16px 18px"><div class="row" style="justify-content:space-between;flex-wrap:nowrap"><span class="row" style="gap:8px"><span style="font-size:22px;font-weight:500">${d.ccy}</span><span class="vd ${L?'vw':'vr'}" style="font-size:13px">${L?'Long':'Short'} · ${d.lever}× isolated</span></span><span class="sub n">conviction ${d.conv}</span></div>
<div class="sub n" style="margin:2px 0 8px">${d.instId} · price ${d.last} · as of ${d.asof}</div>
${row('Entry',d.entry,d.entryNote)}${row('Take profit 1 · half',d.tp1,d.tp1Pct,'up')}${row('Take profit 2 · half',d.tp2,d.tp2Pct,'up')}${row('Stop loss',d.stop,d.stopPct,'dn')}${row('Size',d.contracts+' contracts','≈ '+d.notional+' USDT · margin '+d.margin)}
<div class="g" style="grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;margin:10px 0 12px">${[['Risk at stop','−'+d.loss+' USDT',d.lossPct+' of '+d.balance,'dn'],['Gain at targets','+'+d.gain+' USDT','both filled','up'],['Reward : risk',d.rr+' : 1','blended','']].map(a=>`<div style="background:var(--surface-0);border-radius:8px;padding:7px 9px;min-width:0"><div class="lbl" style="font-size:11px;white-space:nowrap">${a[0]}</div><div class="n ${a[3]}" style="font-size:15px;font-weight:500;white-space:nowrap">${a[1]}</div><div class="sub n" style="font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${a[2]}</div></div>`).join('')}</div>
<button data-go="1" style="width:100%;padding:11px;font-size:15px;font-weight:500">Confirm order ↗</button>
<details style="margin-top:10px"><summary style="cursor:pointer;font-size:12.5px;color:var(--text-secondary)">How these numbers were set</summary><div style="margin-top:6px">${d.notes.map(n=>`<div class="fl" style="padding:2px 0"><span style="flex:none;width:68px;color:var(--text-muted)">${n[0]}</span><span>${n[1]}</span></div>`).join('')}</div></details></div>`;
el.querySelector('button[data-go]').onclick=()=>window.sendPrompt&&sendPrompt(`Confirm — place the ${d.ccy} ${d.side} on the demo account.`)}
window.ATK={analysis,conclusion,dcdAnalysis,dcdConclusion,radarScan,radarCandidates,radarPlan,radar,positionCard,version:'2.0.0'};

